#!/usr/bin/env bash
#Code generated by Claude Opus 5.5
set -euo pipefail
cd "$(dirname "$0")"
mvn -q -DskipTests compile
export RUN_ID=$(date +%s)

pids=()
trap 'kill "${pids[@]}" 2>/dev/null || true' EXIT INT TERM

dapr run --app-id coordinator --dapr-http-port 3500 --dapr-grpc-port 50001 --resources-path ./config \
  -- mvn -q exec:java -Dexec.mainClass=uc4.CoordinatorKt &
coord=$!
sleep 8
for i in 1 2 3; do
  dapr run --app-id sensor-$i --dapr-http-port 350$i --dapr-grpc-port 5000$((i+1)) --resources-path ./config \
    -- mvn -q exec:java -Dexec.mainClass=uc4.SensorKt -Dexec.args="$i" &
  pids+=("$!")
done
wait "$coord"
